/* GPlanSiS|PDIN · Renderização dos módulos (operacional). Só produz HTML a partir de App.state; ações ficam em app.js (data-*). */
'use strict';
const Modules=(()=>{
const stName=i=>App.state.stages[i]?App.state.stages[i].name:'—';
const cx={basic:['Básico','info'],advanced:['Avançado','accent'],expert:['Especialista','purple']};
const SB={backlog:'',planned:'info',released:'accent',running:'ok',paused:'warn',done:'ok',cancelled:''};
const statusBadge=o=>`<span class="badge ${SB[o.status]||''}">${F.STATUS_LABEL[o.status]}</span>`;
const oeeClass=v=>v>=.85?'ok':v>=.6?'warn':'alarm';
const minutes=m=>m>=120?(m/60).toFixed(1)+' h':Math.round(m)+' min';
const orderLink=(o,extra)=>`<b class="mono link-order" data-open-order="${o.id}" ${extra||''}>${o.id}</b>`;
function opBadge(op){return `<span class="op-status ${op.status}"></span>`;}
function pickBadge(o){if(o.consumed)return '<span class="badge ok">Kit entregue</span>';const pend=F.pendencies(App.state).filter(p=>p.order===o.id);return pend.length?`<span class="badge alarm" title="${pend.map(p=>App.state.stock[p.item].code+' falta '+p.missing).join(', ')}">Falta material</span>`:'<span class="badge warn picking-pending">Picking pendente</span>';}
function routeDots(o){return '<div class="route" title="'+o.ops.map(op=>stName(op.stage)+(op.rework?' (retrab.)':'')).join(' → ')+'">'+o.ops.map((op,k)=>`<i class="${op.status==='done'?'done':k===o.step&&o.status!=='done'?'cur':''}"></i>`).join('')+'</div>';}
function opControls(o){const s=App.state,op=F.curOp(o);if(!op||['done','cancelled'].includes(o.status))return '';const b=[];
 if(op.status==='pending'){if(o.step>F.consumeStep(s,o)&&!o.consumed)b.push(`<button data-order="${o.id}" data-act="pick" class="primary">Picking</button>`);b.push(`<button data-order="${o.id}" data-act="start" class="${o.consumed||o.step<=F.consumeStep(s,o)?'primary':''}">▶ Iniciar</button>`);}
 if(op.status==='running'){b.push(`<button data-order="${o.id}" data-act="finish" class="primary">✓ Concluir</button><button data-order="${o.id}" data-act="pause">Ⅱ Pausar</button><button data-order="${o.id}" data-act="reject" class="danger">NC</button>`);}
 if(op.status==='paused'){b.push(`<button data-order="${o.id}" data-act="resume" class="primary">▶ Retomar</button><button data-order="${o.id}" data-act="finish">✓ Concluir</button>`);}
 if(o.step===F.consumeStep(s,o)&&!o.consumed&&op.status!=='pending')b.push(`<button data-order="${o.id}" data-act="pick">Picking</button>`);
 return '<div class="actions">'+b.join('')+'</div>';}
function orderRows(list){const s=App.state;return list.map(o=>{const op=F.curOp(o);const pr=F.progress(s,o);return `<tr data-open-order="${o.id}"><td>${orderLink(o)}<small>${esc(o.client)}</small></td><td>${esc(o.productCode)}<small>Rev. ${o.revision} · ${o.qty} un${o.rework?' · '+o.rework+' retrab.':''}</small></td><td>${o.status==='done'?'Expedida '+time(o.completed):o.status==='cancelled'?'—':`${String(o.step+1).padStart(2,'0')}/${o.ops.length} ${esc(stName(op.stage))}${op.status==='running'?' <small style="display:inline;color:var(--ok)">· '+s.stages[op.stage].resources[op.lane]+' · '+Math.round(s.time-op.start)+' min</small>':''}`}<div class="progress ${o.status==='done'?'ok':op&&op.status==='running'?'':'info'}"><i style="width:${o.status==='done'?100:pr}%"></i></div>${routeDots(o)}</td><td>${statusBadge(o)} ${o.priority==='Urgente'?'<span class="badge warn">Urgente</span>':''}<div style="margin-top:4px">${['done','cancelled'].includes(o.status)?'':pickBadge(o)}</div></td><td class="num">${time(o.due)}${o.due<s.time&&!['done','cancelled'].includes(o.status)?'<small style="color:var(--danger)">Vencida</small>':o.plannedEnd?`<small>plano ${time(o.plannedEnd)}</small>`:''}</td><td>${opControls(o)}</td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">Nenhuma ordem encontrada.</td></tr>';}
function bar(label,v,extra){return `<div class="bar-row"><span title="${esc(label)}">${esc(label)}</span><div class="track"><i class="${oeeClass(v)}" style="width:${Math.round(v*100)}%"></i></div><span class="num">${pct(v)}${extra||''}</span></div>`;}

const metrics={render(){const s=App.state,k=F.kpis(s);const data=[['Carteira / liberadas',k.backlog+' / '+k.released,'',k.open+' ordens abertas','var(--info)'],['Em produção agora',k.running,'op.',k.load+'% das '+k.cap+' posições','var(--ok)'],['Pickings pendentes',k.pickingPending,'',k.pendencies+' pendências de material',k.pickingPending?'var(--warn)':'var(--ink3)'],['OEE',Math.round(k.oee*100),'%','A '+pct(k.availability)+' · P '+pct(k.performance)+' · Q '+pct(k.quality),oeeClass(k.oee)==='ok'?'var(--ok)':oeeClass(k.oee)==='warn'?'var(--warn)':'var(--danger)'],['Vencidas',k.late,'OPs','OTIF '+(k.otif==null?'—':k.otif+'%')+' · '+k.done+' concluídas',k.late?'var(--danger)':'var(--ink3)'],['Alarmes',k.alarms,'ativos',k.down+' falhas · '+k.stopped+' paradas',k.alarms?'var(--warn)':'var(--ink3)']];$('metrics').innerHTML=data.map(([l,v,u,n,c])=>`<div class="metric" style="--metric:${c}"><div class="metric-label">${l}</div><div class="metric-value">${v}<em>${u}</em></div><div class="metric-note">${n}</div></div>`).join('');}};

const projects={render(){const list=App.projects;const cards=list.map(p=>{const cur=App.project&&p.id===App.project.id;const c=cx[p.complexity]||cx.basic;return `<article class="project-card ${cur?'current':''}"><div class="panel-title" style="margin:0"><span class="tag ${p.kind==='demo'?'info':'accent'}">${p.kind==='demo'?'VALIDAÇÃO':'OPERACIONAL'}</span><span class="badge ${c[1]}">${c[0]}</span></div><h3>${esc(p.name)}</h3><small>${esc(p.industry||'')} · <span class="mono">${esc(p.code)}</span></small><p>${esc(p.description||'')}</p><div class="stats"><div><b>${p.open_orders??'—'}</b><small>abertas</small></div><div><b>${p.completed_orders??'—'}</b><small>concluídas</small></div><div><b>${p.work_centers??'—'}</b><small>setores</small></div><div><b>${p.products??'—'}</b><small>produtos</small></div></div><div class="foot"><small>${p.saved_at?'Gravado '+new Date(p.saved_at).toLocaleString('pt-BR'):'Sem estado gravado'}</small><div class="actions">${cur?'<span class="badge accent">Ativo</span>':`<button class="primary" data-open-project="${p.id}">Abrir</button>`}${(App.online||p.custom)?`<button data-archive-project="${p.id}" class="ghost">Arquivar</button>`:''}</div></div></article>`;}).join('');
 $('view-projects').innerHTML=`<div class="notice ${App.online?'ok':'warn'}">${App.online?`Conectado ao PostgreSQL <b>${esc(App.health?.db||'')}</b> (migração ${App.health?.migration}). Ordens, apontamentos, revisões, estoque e estados são persistidos e reconciliados no banco.`:'API indisponível. Projetos e estado persistem apenas neste navegador. Inicie <code>INICIAR.ps1</code> para usar o PostgreSQL.'} · ${list.length} projeto(s) ativo(s) · <a href="#portfolio" class="link-order">ver portfólio unificado ↗</a></div><div class="project-grid">${cards}<button class="project-card new" id="new-project-card" type="button"><span class="plus">＋</span><h3>Novo projeto de fábrica</h3><p>A partir de um modelo de indústria ou totalmente personalizado.</p></button></div>`;
 $('new-project-card').onclick=()=>$('new-project').click();}};

/* Portfólio: janela de montagem de todos os projetos no mesmo Gantt + carga combinada por setor/dia */
const PCOL=['#58a6ff','#f0883e','#3fb950','#a371f7','#d29922','#39c5cf','#f85149','#8b949e'];
const portfolio={render(){const v=$('view-portfolio');const list=App.portfolio;if(!list){v.innerHTML='<div class="panel"><div class="empty">Carregando projetos…</div></div>';return;}
 const now=F.now();const plans=list.map((x,i)=>({...x,color:PCOL[i%PCOL.length],plan:F.schedule(x.state,'rank',false)}));
 const horizon=Math.max(now+DAYS*1440,...plans.map(p=>p.plan.horizon));const from=now-120,span=Math.min(horizon,now+DAYS*1440)-from;
 const rows=plans.map(p=>{const s=p.state;const orders=s.orders.filter(o=>!['done','cancelled'].includes(o.status)).map(o=>{const jobs=p.plan.jobs.filter(j=>j.id===o.id);const start=Math.min(...jobs.map(j=>j.start),o.ops.filter(x=>x.start).map(x=>x.start).reduce((a,b)=>Math.min(a,b),Infinity));const end=p.plan.finish[o.id]||o.due;return {o,start:Number.isFinite(start)?start:now,end,late:end>o.due};}).sort((a,b)=>a.start-b.start);const k=F.kpis(s);return `<div class="pf-row project"><div class="pf-label" style="border-left:3px solid ${p.color};padding-left:8px">${esc(s.project.name)}<small>${orders.length} abertas · ${p.plan.late} atraso previsto · ocupação ${k.load}%</small></div><div class="pf-track">${orders.length?`<div class="pf-bar" style="left:${Math.max(0,(Math.min(...orders.map(r=>r.start))-from)/span*100)}%;width:${Math.min(100,(Math.max(...orders.map(r=>r.end))-Math.max(from,Math.min(...orders.map(r=>r.start))))/span*100)}%;background:${p.color};opacity:.35"></div>`:''}<div class="pf-now" style="left:${(now-from)/span*100}%"></div></div></div>`+orders.slice(0,25).map(r=>`<div class="pf-row"><div class="pf-label"><span class="link-order" data-open-order="${r.o.id}" data-project="${p.project.id}">${r.o.id}</span><small>${esc(r.o.client)} · ${esc(r.o.productCode)} · ${F.STATUS_LABEL[r.o.status]}</small></div><div class="pf-track"><div class="pf-bar ${r.late?'late':''}" data-open-order="${r.o.id}" data-project="${p.project.id}" style="left:${Math.max(0,(r.start-from)/span*100)}%;width:${Math.max(.4,(Math.min(r.end,from+span)-Math.max(r.start,from))/span*100)}%;background:${p.color}" title="${r.o.id} · ${time(r.start)} → ${time(r.end)} · prazo ${time(r.o.due)}">${r.o.id}${r.late?' ⚠':''}</div><div class="pf-now" style="left:${(now-from)/span*100}%"></div></div></div>`).join('');}).join('');
 /* capacidade combinada: setores agrupados por id (mesmo nome de setor em projetos diferentes = mesma família) */
 const cap={};plans.forEach(p=>{const lp=F.loadProfile(p.state,p.plan,DAYS);lp.rows.forEach(r=>{const key=r.stage;const c=cap[key]||(cap[key]={name:r.name,capacity:0,days:Array(DAYS).fill(0),projects:{}});c.capacity+=r.capacityPerDay;r.days.forEach((m,i)=>c.days[i]+=m);c.projects[p.state.project.code]=(c.projects[p.state.project.code]||0)+r.days.reduce((a,b)=>a+b,0);});});
 const d0=new Date();d0.setHours(0,0,0,0);const dayLabels=Array.from({length:DAYS},(_,i)=>{const d=new Date(d0.getTime()+i*86400000);return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0');});
 const total=plans.reduce((n,p)=>n+p.state.orders.filter(o=>!['done','cancelled'].includes(o.status)).length,0);
 v.innerHTML=`<div class="tiles"><div class="tile"><small>Projetos ativos</small><b>${plans.length}</b></div><div class="tile"><small>Ordens abertas</small><b>${total}</b></div><div class="tile"><small>Atraso previsto</small><b>${plans.reduce((n,p)=>n+p.plan.late,0)}</b><small>ordens após o prazo</small></div><div class="tile"><small>Em produção agora</small><b>${plans.reduce((n,p)=>n+F.kpis(p.state).running,0)}</b><small>de ${plans.reduce((n,p)=>n+F.kpis(p.state).cap,0)} posições</small></div><div class="tile"><small>Horizonte</small><b>${Math.ceil((horizon-now)/1440)}<em style="font:11px var(--sans);font-style:normal"> d</em></b><small>até a última expedição prevista</small></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Janela de montagem · todos os projetos</h2><div class="toolbar" style="margin:0"><span class="muted">${App.online?'estados do PostgreSQL':'estados locais'} · clique em uma barra para abrir a OP</span><button id="refresh-portfolio" class="small">Atualizar</button></div></div><div class="pf-legend">${plans.map(p=>`<span><i style="background:${p.color}"></i>${esc(p.state.project.code)}</span>`).join('')}<span><i style="background:transparent;outline:1.5px solid var(--danger)"></i>término previsto após o prazo</span></div><div class="table-wrap" style="max-height:none"><div style="min-width:760px"><div class="pf-times">${Array.from({length:8},(_,i)=>`<span>${time(from+span*i/7)}</span>`).join('')}</div>${rows}</div></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Capacidade combinada por setor e dia</h2><span class="muted">minutos planejados ÷ minutos disponíveis (posições × turno) · soma dos projetos</span></div><div class="cap-grid" style="--days:${DAYS}"><div></div>${dayLabels.map(l=>`<div class="h">${l}</div>`).join('')}${Object.entries(cap).map(([id,c])=>`<div class="pf-label" title="${Object.entries(c.projects).map(([k,m])=>k+': '+minutes(m)).join(' · ')}">${esc(c.name)}<small>${Math.round(c.capacity/60)} h/dia</small></div>${c.days.map(m=>{const r=c.capacity?m/c.capacity:0;return `<div class="cap-cell ${r>1?'alarm':r>.85?'warn':''}" title="${minutes(m)} de ${minutes(c.capacity)}"><i style="width:${Math.min(100,r*100)}%"></i><span>${Math.round(r*100)}%</span></div>`;}).join('')}`).join('')}</div></div>`;}};
const DAYS=10;

const twin={render(){const s=App.state,k=F.kpis(s);$('pulse').innerHTML=[['◴','Posições em operação','Apontamentos em andamento',k.running+'/'+k.cap],['▥','Pickings pendentes','Kits a separar no almoxarifado',k.pickingPending],['⚡','Setores indisponíveis','Falhas + paradas programadas',k.down+k.stopped],['↗','Ordens expedidas','Concluídas neste projeto',k.done]].map(([i,t,sub,v])=>`<div class="pulse-row"><span class="pulse-icon">${i}</span><div><strong>${t}</strong><small>${sub}</small></div><b>${v}</b></div>`).join('');
 if(!s.stages.some(x=>x.id===App.selected))App.selected=s.stages[0].id;const i=F.stageIndex(s,App.selected),st=s.stages[i],q=F.queue(s,i),run=F.runningAt(s,i),o=F.oee(st);$('asset-name').textContent=st.name;$('asset-desc').textContent=st.down?'Em falha: '+st.down.reason+' · retorno previsto '+time(st.down.until):s.stops[st.id]?'Parada programada · fila aguardando retomada.':'Etapa '+String(i+1).padStart(2,'0')+' · '+st.setup+' min setup + '+st.minutes+' min/un · '+st.capacity+' posição(ões)'+(st.yield<1?' · rendimento alvo '+pct(st.yield):'');
 $('asset-stats').innerHTML=`<div class="asset-grid"><div><small>Na fila</small><strong>${q.length}</strong></div><div><small>Executando</small><strong>${run.length}/${st.capacity}</strong></div><div><small>OEE</small><strong>${pct(o.oee)}</strong></div></div>`;
 $('asset-queue').innerHTML=(run.map(x=>`<div class="event ok"><i></i><span>${orderLink(x.o)} · ${st.resources[x.op.lane]} · ${Math.round(s.time-x.op.start)} min</span></div>`).join('')+q.slice(0,4).map(x=>`<div class="event"><i></i><span>${orderLink(x)} · aguardando · ${esc(x.client)}</span></div>`).join(''))||'<small>Sem ordens neste setor.</small>';
 $('failure').textContent=s.stops[st.id]?'▷ Retomar setor':'⚡ Registrar parada';
 $('flow-stages').innerHTML='<div class="stage-grid">'+s.stages.map((st,i)=>{const n=F.queue(s,i).length+F.runningAt(s,i).length;const bad=st.down||s.stops[st.id];return `<button class="stage-item ${st.id===App.selected?'active':''} ${bad?'down':''}" data-stage="${st.id}" title="${esc(st.name)}"><span>${String(i+1).padStart(2,'0')}<em>${st.down?'FALHA':s.stops[st.id]?'PARADO':F.runningAt(s,i).length+'/'+st.capacity}</em></span><b>${n}</b><small>${esc(st.name)}</small><div class="mini-bar"><i style="width:${Math.min(100,n/st.capacity*50)}%;background:${bad?'var(--danger)':n>st.capacity*2?'var(--warn)':'var(--accent)'}"></i></div></button>`;}).join('')+'</div>';
 const al=F.alarms(s);$('andon-count').textContent=al.length+' ativo(s)';$('andon-count').className='tag '+(al.some(a=>a.sev==='alarm')?'alarm':al.length?'warn':'ok');$('andon').innerHTML=al.slice(0,8).map(a=>`<div class="alarm ${a.sev}-sev"><b>${a.kind}</b><span>${a.order?`<span class="link-order" data-open-order="${a.order}">${a.order}</span>${esc(a.text.slice(a.order.length))}`:esc(a.text)}</span></div>`).join('')||'<div class="empty">Sem alarmes ativos.</div>';
 $('events').innerHTML=s.events.slice(0,8).map(e=>`<div class="event ${e.kind}"><time>${time(e.time)}</time><i></i><span>${esc(e.text)}</span></div>`).join('');
 const rd=F.processReadings(s);if(rd.length){const live=rd.filter(r=>r.value!=null).length;$('tele-count').textContent=live+'/'+rd.length+' tags';$('tele-count').className='tag '+(rd.some(r=>r.state==='deviation')?'alarm':live?'ok':'warn');const sel=rd.filter(r=>r.stage===App.selected);const list=(sel.length?sel:rd.filter(r=>r.order)).slice(0,10);$('telemetry').innerHTML=list.map(r=>`<div class="alarm ${r.state==='deviation'?'alarm-sev':r.state==='ok'?'':'warn-sev'}"><b>${esc(r.resource||r.stage)}</b><span><span class="mono">${esc(r.tag)}</span> ${r.value==null?'<span class="muted">sem dados</span>':`<b class="num">${r.value.toFixed(r.unit==='un'?0:1)} ${esc(r.unit)}</b>`}${r.setpoint!=null?` <small style="display:inline">· sp ${r.setpoint}±${(r.hi-r.setpoint).toFixed(1)}</small>`:r.lo!=null||r.hi!=null?` <small style="display:inline">· ${r.lo??'—'}…${r.hi??'—'}</small>`:''}${r.order?` <span class="link-order" data-open-order="${r.order}">${r.order}</span>`:''}${r.state==='stale'?' <span class="badge warn">obsoleto</span>':r.state==='bad'?' <span class="badge alarm">qualidade</span>':r.state==='deviation'?' <span class="badge alarm">desvio</span>':''}</span></div>`).join('')||'<small>Selecione um setor com instrumentação.</small>';}}};

const mes={render(force){const s=App.state,v=$('view-mes');if(force||!v.querySelector('#mes-rows'))v.innerHTML=`<div class="panel"><div class="toolbar"><input id="order-search" aria-label="Buscar ordens" placeholder="Buscar ordem, cliente ou produto…" value="${esc(App.search)}"><select id="stage-filter" aria-label="Filtrar setor"><option value="">Todos os setores</option>${s.stages.map(x=>`<option value="${x.id}" ${App.filter===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="status-filter" aria-label="Filtrar status"><option value="">Chão de fábrica (liberadas + produção)</option>${[['all','Todas'],['released','Liberadas'],['running','Em produção'],['paused','Pausadas'],['picking','Picking pendente'],['late','Vencidas'],['done','Concluídas']].map(([k,l])=>`<option value="${k}" ${App.statusFilter===k?'selected':''}>${l}</option>`).join('')}</select><span class="tag">${s.settings.calendar?s.settings.shifts.length+' TURNO(S)':'CONTÍNUO'}</span></div><div class="table-wrap"><table><thead><tr><th>Ordem / cliente</th><th>Produto</th><th>Operação atual · avanço · roteiro</th><th>Status · materiais</th><th>Prazo</th><th>Apontamento</th></tr></thead><tbody id="mes-rows"></tbody></table></div></div><div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Setores · posições, fila e OEE</h2><span class="muted">clique no setor para inspecionar no gêmeo</span></div><div class="table-wrap" style="max-height:none"><table><thead><tr><th>Setor</th><th>Estado</th><th>Posições</th><th>Fila</th><th>Setup / un</th><th>OEE</th><th>Boas / NC</th><th>Ações</th></tr></thead><tbody id="mes-stages"></tbody></table></div></div>`;
 const q=App.search.toLowerCase(),f=App.statusFilter;const list=s.orders.filter(o=>{if(!f)return ['released','running','paused'].includes(o.status);if(f==='all')return true;if(f==='late')return o.due<s.time&&!['done','cancelled'].includes(o.status);if(f==='picking')return ['released','running','paused'].includes(o.status)&&!o.consumed;return o.status===f;}).filter(o=>(!App.filter||s.stages[F.cur(o)]?.id===App.filter)&&[o.id,o.client,o.productCode].join(' ').toLowerCase().includes(q)).sort((a,b)=>(a.status==='running'?0:1)-(b.status==='running'?0:1)||a.rank-b.rank);$('mes-rows').innerHTML=orderRows(list);
 $('mes-stages').innerHTML=s.stages.map((st,i)=>{const qq=F.queue(s,i),run=F.runningAt(s,i),o=F.oee(st);return `<tr><td><button class="ghost" data-stage="${st.id}" style="padding:0;text-align:left"><b>${esc(st.name)}</b></button><small class="mono">${st.resources.map(r=>`<button class="ghost small" style="padding:0 2px" data-focus-resource="${esc(r)}" data-stage="${st.id}">${esc(r)}</button>`).join(' · ')}</small></td><td>${st.down?'<span class="badge alarm">Falha</span>':s.stops[st.id]?'<span class="badge warn">Parado</span>':run.length?'<span class="badge ok">Produzindo</span>':'<span class="badge">Livre</span>'}</td><td class="num">${run.length}/${st.capacity}${run.length?`<small>${run.map(x=>x.o.id).join(', ')}</small>`:''}</td><td class="num">${qq.length}${qq.length?`<small>${qq.slice(0,3).map(x=>x.id).join(', ')}${qq.length>3?'…':''}</small>`:''}</td><td class="num">${st.setup} / ${st.minutes} min</td><td class="num">${pct(o.oee)}</td><td class="num">${st.good} / ${st.scrap}</td><td><div class="actions">${st.down?`<button data-repair="${st.id}" class="primary">Reparo concluído</button>`:`<button data-stop="${st.id}">${s.stops[st.id]?'Retomar':'Parada'}</button>`}</div></td></tr>`;}).join('');}};

const aps={render(force){const s=App.state,v=$('view-aps');const plan=F.schedule(s,App.rule,false);const plans={};Object.keys(F.RULES).forEach(r=>plans[r]=r===App.rule?plan:F.schedule(s,r,false));const now=s.time;const from=now-30;const zoom=App.ganttZoom;const span=Math.max(480,(plan.horizon-from)*1.02)/zoom;
 if(force||!v.querySelector('#gantt'))v.innerHTML=`<div class="panel"><div class="panel-title"><h2>Programação com capacidade finita</h2><div class="toolbar" style="margin:0"><span class="muted">zoom</span>${[1,2,4].map(z=>`<button data-zoom="${z}" class="small ${App.ganttZoom===z?'primary':''}">${z}×</button>`).join('')}<button class="primary" id="apply-plan">Aplicar regra selecionada</button></div></div><div class="compare" id="aps-compare"></div><div id="aps-summary"></div><div class="gantt-legend"><span><i style="background:var(--info-soft);border-color:var(--info)"></i>planejada</span><span><i style="background:var(--ok-soft);border-color:var(--ok)"></i>em execução</span><span><i style="background:var(--warn-soft);border-color:var(--warn)"></i>pausada / urgente</span><span><i style="background:var(--danger-soft);border-color:var(--danger)"></i>termina após o prazo</span><span><i style="background:var(--purple-soft);border-color:var(--purple)"></i>retrabalho</span><span><i style="border-style:dashed;border-color:var(--ink2)"></i>fixada (arrastada ou recurso definido)</span></div><div class="table-wrap" style="max-height:none"><div id="gantt" class="gantt"></div></div></div>`;
 $('aps-compare').innerHTML=Object.entries(F.RULES).map(([r,l])=>`<button data-rule="${r}" class="${r===App.rule?'selected':''}"><small>${l}</small><b>${plans[r].late} <span class="muted">atrasadas</span></b><small>makespan ${Math.round(plans[r].makespan/60)} h · ${plans[r].orders} ordens</small></button>`).join('');
 $('aps-summary').innerHTML=`<div class="notice">${plan.orders} ordens programadas · ${plan.late} com término previsto após o prazo · horizonte ${Math.round(plan.makespan/60)} h · ${s.planned} recálculo(s). <b>Arraste</b> uma operação para fixar novo início (e solte em outra pista para trocar o recurso): toda a programação é empurrada para frente. <b>Clique</b> na barra para abrir a gaveta da OP. Operações em execução ocupam a posição real.</div>`;
 const ticks=Array.from({length:9},(_,i)=>from+span*i/8);
 $('gantt').innerHTML=`<div class="gantt-times">${ticks.map(t=>`<span>${time(t)}</span>`).join('')}</div>`+s.stages.map((st,i)=>Array.from({length:st.capacity},(_,lane)=>`<div class="gantt-row"><div class="gantt-label"><b>${esc(st.name)}</b> <span class="muted">${st.resources[lane]}</span></div><div class="gantt-track" data-stage="${i}" data-lane="${lane}" data-span="${span}" data-t0="${from}">${shiftShade(s,from,span)}<div class="gantt-now" style="left:${(now-from)/span*100}%"></div>${plan.jobs.filter(j=>j.stage===i&&j.lane===lane).map(j=>{const o=s.orders.find(x=>x.id===j.id);const cls=j.status==='running'?'running':j.status==='paused'?'paused':j.late?'late':j.rework?'rework':o.priority==='Urgente'?'urgent':'';return `<span class="gantt-bar ${cls} ${j.pinned?'pinned':''} ${App.drawer===j.id?'selected':''}" data-order="${j.id}" data-op="${j.seq}" data-stage="${i}" style="left:${(j.start-from)/span*100}%;width:${Math.max(.3,(j.end-j.start)/span*100)}%" title="${j.id} · op ${j.seq} · ${esc(o.client)} · ${time(j.start)} → ${time(j.end)}${j.pinned?' · fixada':''}">${j.id}</span>`;}).join('')}</div></div>`).join('')).join('');}};
function shiftShade(s,from,span){if(!s.settings.calendar)return '';const out=[];const dayStart=t=>{const d=new Date(t*60000);d.setHours(0,0,0,0);return d.getTime()/60000;};let d=dayStart(from);while(d<from+span){const off=[];let prev=0;const sh=s.settings.shifts.slice().sort((a,b)=>a[0]-b[0]);sh.forEach(([a,b])=>{if(a>prev)off.push([prev,a]);prev=Math.max(prev,b);});if(prev<1440)off.push([prev,1440]);off.forEach(([a,b])=>{const x0=Math.max(from,d+a),x1=Math.min(from+span,d+b);if(x1>x0)out.push(`<div class="gantt-shift" style="left:${(x0-from)/span*100}%;width:${(x1-x0)/span*100}%"></div>`);});d+=1440;}return out.join('');}

const plm={render(){const s=App.state;const pend=F.pendencies(s);$('view-plm').innerHTML=`<div class="notice">Estrutura (BOM) e roteiro são congelados em cada ordem na criação. <b>Importar BOM</b> traz a lista da engenharia como revisão em análise (itens novos entram no catálogo com saldo zero e viram pendência de material). Liberar afeta apenas novas ordens.${App.online?' Revisões são gravadas no PostgreSQL com imutabilidade após liberação.':''}</div><div class="module-grid">${s.products.map((p,i)=>`<article class="product"><div class="product-top"><div><span class="eyebrow">${esc(p.code)} / engenharia</span><h3>${esc(p.name)}</h3><div class="chips"><span class="chip on">Rev. ${p.rev} liberada</span>${p.draft?`<span class="chip">Rev. ${p.draft.rev} em análise${p.draft.imported?' · importada':''}</span>`:''}<span class="chip">${s.orders.filter(o=>o.product===i&&o.status!=='cancelled').length} ordens</span></div></div></div><h3 style="font-size:12px;margin-top:8px">Estrutura de materiais <span class="muted">/ por unidade · disponível no almoxarifado</span></h3><ul>${p.bom.map(b=>{const x=s.stock[b.item],av=x.onHand-x.reserved;return `<li><span>${esc(x.name)} <small class="mono" style="display:inline">${esc(x.code)}</small></span><span><b>${b.qty} ${x.unit}</b> <span class="badge ${av<x.min?'warn':'ok'}" style="margin-left:6px">${av} ${x.unit}</span></span></li>`;}).join('')}</ul>${p.draft?`<div class="notice warn" style="margin:8px 0"><b>Proposta ${p.draft.rev}</b> · ${esc(p.draft.note||'sem alteração de BOM')}<ul style="margin:6px 0 0">${p.draft.bom.map(b=>{const x=s.stock[b.item];const cur=p.bom.find(k=>k.item===b.item);return `<li style="padding:3px 0;border:0"><span>${esc(x.code)} ${esc(x.name)}${x.imported?' <span class="badge info">novo</span>':''}</span><b>${cur?cur.qty+' → ':''}${b.qty} ${x.unit}</b></li>`;}).join('')}${p.bom.filter(b=>!p.draft.bom.some(d=>d.item===b.item)).map(b=>`<li style="padding:3px 0;border:0;opacity:.6"><span>${esc(s.stock[b.item].code)} removido</span><b>${b.qty} → 0</b></li>`).join('')}</ul></div>`:''}<h3 style="font-size:12px">Roteiro <span class="muted">/ ${p.route.length} operações · ${Math.round(p.route.reduce((n,i)=>n+s.stages[i].setup+s.stages[i].minutes,0))} min base</span></h3><div class="chips">${p.route.map(i=>`<span class="chip">${esc(s.stages[i].name)}</span>`).join('')}</div><div class="product-actions"><button data-import-bom="${i}" ${p.draft?'disabled':''}>⇪ Importar BOM</button><button data-revise="${i}" ${p.draft?'disabled':''}>＋ Propor revisão</button><button class="primary" data-release="${i}" ${!p.draft?'disabled':''}>Liberar ${p.draft?p.draft.rev:'revisão'}</button>${p.draft?`<button class="ghost" data-discard="${i}">Descartar</button>`:''}</div></article>`).join('')}</div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Pendências de material · engenharia × almoxarifado × produção</h2><span class="tag ${pend.length?'warn':'ok'}">${pend.length} pendência(s)</span></div><div class="table-wrap"><table class="pend-table"><thead><tr><th>Ordem</th><th>Item</th><th>Necessário</th><th>Físico</th><th>Falta</th><th>Compra em trânsito</th><th>Chegada</th><th>Ações</th></tr></thead><tbody>${pend.map(pd=>{const x=s.stock[pd.item],o=s.orders.find(k=>k.id===pd.order);return `<tr><td>${orderLink(o)}<small>${esc(o.client)} · ${F.STATUS_LABEL[o.status]}</small></td><td>${esc(x.name)}<small class="mono">${esc(x.code)}</small></td><td class="num">${pd.need} ${x.unit}</td><td class="num">${pd.onHand}</td><td class="num" style="color:var(--danger)">${pd.missing}</td><td class="num">${pd.open}</td><td class="num">${pd.eta?time(pd.eta):'—'}</td><td><div class="actions"><button data-receive="${pd.item}" data-kind="purchase">Comprar</button><button data-receive="${pd.item}" data-kind="receive">Receber</button></div></td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">Todas as ordens abertas têm material físico para o picking.</td></tr>'}</tbody></table></div></div>`;}};

/* PCP · Kanban arrastável por status */
const ppcp={render(){const s=App.state;const cols=[['backlog','Carteira'],['planned','Planejada'],['released','Liberada'],['running','Em produção'],['paused','Pausada'],['done','Concluída']];const sug=F.suggestions(s),openPO=s.purchases.filter(p=>p.status==='open');const open=s.orders.filter(o=>!['done','cancelled'].includes(o.status));
 $('view-ppcp').innerHTML=`<div class="grid-2 split-2-1"><div class="notice" style="margin:0">${open.reduce((n,o)=>n+o.qty,0)} unidades em ${open.length} ordens abertas · ${open.filter(o=>o.priority==='Urgente').length} urgentes · ${open.filter(o=>o.due<s.time).length} vencidas. <b>Arraste</b> os cartões entre colunas para mudar o status e dentro da coluna para sequenciar (a ordem da coluna é a sequência do APS). Clique no código para abrir a gaveta e planejar datas e recursos.</div><div class="panel" style="padding:10px 14px"><div class="panel-title" style="margin-bottom:6px"><h2>MRP · necessidades</h2><button id="run-mrp" class="small">Rodar MRP</button></div>${sug.length?sug.slice(0,6).map(r=>`<div class="alarm warn-sev" style="margin-bottom:4px"><b>compra</b><span>${esc(s.stock[r.item].name)}: disp. ${r.available} + ${r.open} em trânsito${r.shortage?' · falta '+r.shortage+' p/ ordens':''} · sugerido ${r.shortfall} ${s.stock[r.item].unit}</span></div>`).join(''):'<small>Coberturas atendidas'+(openPO.length?' · '+openPO.length+' pedido(s) em trânsito':'')+'.</small>'}${s.settings.autoMrp?'<small style="margin-top:6px">MRP automático horário ativo.</small>':''}</div></div><div class="kanban" style="margin-top:14px">${cols.map(([st,name])=>{const list=s.orders.filter(o=>o.status===st).sort((a,b)=>st==='done'?(b.completed||0)-(a.completed||0):a.rank-b.rank);return `<div class="kanban-column" data-status="${st}"><h2>${name} <span class="badge ${SB[st]||''}">${list.length}</span></h2>${list.slice(0,60).map(o=>{const op=F.curOp(o);return `<div class="order-card" draggable="${st!=='done'}" data-card="${o.id}"><div class="panel-title" style="margin-bottom:4px"><span><span class="card-grip">⋮⋮</span>${orderLink(o)}</span><span class="badge ${o.priority==='Urgente'?'warn':''}">${o.priority==='Urgente'?'Urgente':'#'+(o.rank+1)}</span></div><p>${esc(o.client)} · ${esc(o.productCode)} · ${o.qty} un</p><div class="meta"><span>${o.status==='done'?'expedida '+time(o.completed):'prazo '+time(o.due)+(o.due<s.time?' ⚠':'')}</span><span class="pick">${['done','cancelled'].includes(o.status)?'':pickBadge(o)}</span></div>${op&&o.status!=='done'?`<small style="margin-top:4px">${String(o.step+1).padStart(2,'0')}/${o.ops.length} ${esc(stName(op.stage))}${o.plannedEnd?' · fim previsto '+time(o.plannedEnd):''}</small>`:''}<div class="progress ${o.status==='done'?'ok':'info'}"><i style="width:${o.status==='done'?100:(o.step+F.progress(s,o)/100)/o.ops.length*100}%"></i></div></div>`;}).join('')||'<p class="muted">Solte aqui.</p>'}</div>`;}).join('')}</div>`;}};

const stock={render(){const s=App.state;const coverage=x=>{const i=s.stock.indexOf(x);const daily=s.movements.filter(m=>m.type==='Consumo'&&m.item===i&&m.time>s.time-1440*7).reduce((n,m)=>n-m.qty,0)/7;return daily>0?(x.onHand-x.reserved)/daily:null;};const toPick=s.orders.filter(o=>['released','running','paused'].includes(o.status)&&!o.consumed).sort((a,b)=>a.rank-b.rank);const pend=F.pendencies(s);
 $('view-stock').innerHTML=`<div class="grid-2"><div class="panel"><div class="panel-title"><h2>Picking para produção</h2><span class="tag ${toPick.length?'warn':'ok'}">${toPick.length} kit(s) a separar</span></div><div class="table-wrap"><table><thead><tr><th>Ordem</th><th>Kit</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${toPick.map(o=>{const miss=pend.filter(p=>p.order===o.id);return `<tr><td>${orderLink(o)}<small>${esc(o.client)} · ${esc(o.productCode)} · ${o.qty} un</small></td><td><div class="chips">${o.kit.map(k=>`<span class="chip ${s.stock[k.item].onHand<k.qty?'on':''}">${esc(s.stock[k.item].code)} ${k.qty}</span>`).join('')}</div></td><td>${miss.length?`<span class="badge alarm">falta ${miss.length} item(ns)</span>`:'<span class="badge ok">completo</span>'}</td><td><button data-order="${o.id}" data-act="pick" class="${miss.length?'':'primary'} small" ${miss.length?'disabled':''}>Confirmar picking</button></td></tr>`;}).join('')||'<tr><td colspan="4" class="empty">Nenhum kit pendente.</td></tr>'}</tbody></table></div></div>
 <div class="panel"><div class="panel-title"><h2>Pedidos de compra</h2><span class="muted">${s.purchases.filter(p=>p.status==='open').length} em trânsito</span></div><div class="table-wrap"><table><thead><tr><th>PC</th><th>Item</th><th>Qtd</th><th>Chegada</th><th>Status</th></tr></thead><tbody>${s.purchases.slice(0,25).map(p=>`<tr><td class="mono">${p.id}</td><td>${esc(s.stock[p.item].name)}</td><td class="num">${p.qty} ${s.stock[p.item].unit}</td><td class="num">${time(p.arrive)}</td><td>${p.status==='open'?`<button data-receive-pc="${p.id}" class="small">Receber</button>`:'<span class="badge ok">Recebido '+time(p.received)+'</span>'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum pedido.</td></tr>'}</tbody></table></div></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Posição de estoque</h2><span class="tag">${s.stock.length} SKUs · ALM-01</span></div><div class="table-wrap" style="max-height:none"><table><thead><tr><th>Item / endereço</th><th>Físico</th><th>Reservado</th><th>Disponível</th><th>Mínimo</th><th>Cobertura</th><th>Lead time</th><th>Ações</th></tr></thead><tbody>${s.stock.map((x,i)=>{const av=x.onHand-x.reserved,c=coverage(x),po=s.purchases.filter(p=>p.item===i&&p.status==='open');return `<tr><td><b>${esc(x.name)}</b>${x.imported?' <span class="badge info">novo</span>':''}<small class="mono">${esc(x.code)} · ${esc(x.location)}</small></td><td class="num">${x.onHand} ${x.unit}</td><td class="num">${x.reserved} ${x.unit}</td><td><span class="badge ${av<x.min?'warn':'ok'}">${av} ${x.unit}</span></td><td class="num">${x.min} ${x.unit}</td><td class="num">${c==null?'—':c.toFixed(1)+' d'}</td><td class="num">${x.leadTime} h${po.length?`<small>${po.length} PC em trânsito</small>`:''}</td><td><div class="actions"><button data-receive="${i}" data-kind="receive">＋ Receber</button><button data-receive="${i}" data-kind="purchase">Comprar</button></div></td></tr>`;}).join('')}</tbody></table></div><div class="notice" style="margin:12px 0 0">Criação da OP reserva o kit; o <b>picking</b> consome o estoque e libera a produção a partir de <b>${esc(s.stages[F.stageIndex(s,s.settings.consumeAt)]?.name||s.stages[0].name)}</b>. Disponível = físico − reservado.${App.online?' Recebimentos e consumos são reconciliados no PostgreSQL de forma idempotente a cada gravação.':''}</div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Movimentações</h2><span class="muted">Últimos 30 registros</span></div><div class="table-wrap"><table><thead><tr><th>Hora</th><th>Item</th><th>Tipo</th><th>Qtd</th><th>Origem</th></tr></thead><tbody>${s.movements.slice(0,30).map(m=>`<tr><td class="num">${time(m.time)}</td><td>${esc(s.stock[m.item].name)}</td><td>${m.type}</td><td class="num" style="color:${m.qty>0?'var(--ok)':'var(--ink2)'}">${m.qty>0?'+':''}${m.qty} ${s.stock[m.item].unit}</td><td class="mono">${m.order?`<span class="link-order" data-open-order="${m.order}">${m.order}</span>`:esc(m.ref||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhuma movimentação.</td></tr>'}</tbody></table></div></div>`;}};

const quality={render(){const s=App.state;const good=s.stages.reduce((n,x)=>n+x.good,0),scrap=s.stages.reduce((n,x)=>n+x.scrap,0);const fpy=good+scrap?good/(good+scrap):1;const inProcess=s.orders.filter(o=>o.status==='running'||o.status==='paused');const reworked=s.orders.filter(o=>o.rework>0).sort((a,b)=>b.rework-a.rework);
 $('view-quality').innerHTML=`<div class="tiles"><div class="tile"><small>FPY global</small><b>${pct(fpy)}</b><small>${good} aprovações · ${scrap} NC</small></div><div class="tile"><small>Retrabalhos</small><b>${s.orders.reduce((n,o)=>n+o.rework,0)}</b><small>${reworked.length} ordens afetadas</small></div><div class="tile"><small>Setores com inspeção</small><b>${s.stages.filter(x=>x.yield<1).length}</b><small>rendimento alvo &lt; 100%</small></div><div class="tile"><small>Qualidade OEE</small><b>${pct(F.kpis(s).quality)}</b><small>média dos setores</small></div></div>
 <div class="grid-2" style="margin-top:14px"><div class="panel"><div class="panel-title"><h2>Rendimento por setor</h2><span class="muted">boas / (boas + NC) apontadas</span></div><div class="bars">${s.stages.map(st=>{const t=st.good+st.scrap,q=t?st.good/t:1;return bar(st.name+(st.yield<1?' · alvo '+pct(st.yield):''),q,` <small style="display:inline">${st.good}/${t}</small>`);}).join('')}</div></div>
 <div class="panel"><div class="panel-title"><h2>Registrar não conformidade</h2><span class="muted">${inProcess.length} operações em andamento</span></div><div class="table-wrap"><table><thead><tr><th>Ordem</th><th>Operação atual</th><th>Retrab.</th><th>Ação</th></tr></thead><tbody>${inProcess.slice(0,30).map(o=>`<tr><td>${orderLink(o)}<small>${esc(o.client)} · ${esc(o.productCode)}</small></td><td>${esc(stName(F.cur(o)))}<small>${s.stages[F.cur(o)].resources[F.curOp(o).lane]||''}</small></td><td class="num">${o.rework}</td><td><div class="actions"><button data-order="${o.id}" data-act="reject" class="danger">Registrar NC</button><button data-order="${o.id}" data-act="finish">Concluir c/ refugo</button></div></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nenhuma operação em andamento.</td></tr>'}</tbody></table></div></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Ordens com retrabalho</h2><span class="muted">rastreabilidade por ordem</span></div><div class="table-wrap"><table><thead><tr><th>Ordem / cliente</th><th>Produto</th><th>Operação · roteiro</th><th>Status</th><th>Prazo</th><th>Apontamento</th></tr></thead><tbody>${orderRows(reworked)}</tbody></table></div></div>`;}};

const maint={render(){const s=App.state,k=F.kpis(s);$('view-maint').innerHTML=`<div class="tiles"><div class="tile"><small>Disponibilidade média</small><b>${pct(k.availability)}</b><small>em turno</small></div><div class="tile"><small>Em falha agora</small><b>${k.down}</b><small>setores</small></div><div class="tile"><small>Paradas programadas</small><b>${k.stopped}</b><small>setores</small></div><div class="tile"><small>Falhas acumuladas</small><b>${s.stages.reduce((n,x)=>n+x.breakdowns,0)}</b><small>${Math.round(s.stages.reduce((n,x)=>n+x.downtime,0)/60)} h indisponíveis</small></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Ativos por setor</h2><span class="muted">falhas e paradas são registradas pelo time; nada é gerado automaticamente</span></div><div class="table-wrap" style="max-height:none"><table><thead><tr><th>Setor</th><th>Estado</th><th>MTBF ref.</th><th>MTTR ref.</th><th>Falhas</th><th>Indisponível</th><th>Disponibilidade</th><th>Ações</th></tr></thead><tbody>${s.stages.map(st=>{const o=F.oee(st);return `<tr><td><b>${esc(st.name)}</b><small class="mono">${st.resources.join(' · ')}</small></td><td>${st.down?`<span class="badge alarm">Falha</span><small>${esc(st.down.reason)} · desde ${time(st.down.since)} · previsão ${time(st.down.until)}</small>`:s.stops[st.id]?`<span class="badge warn">Parada programada</span><small>desde ${time(st.stopSince||s.time)}</small>`:'<span class="badge ok">Operacional</span>'}</td><td class="num">${st.mtbf?Math.round(st.mtbf/60)+' h':'—'}</td><td class="num">${st.mttr?st.mttr+' min':'—'}</td><td class="num">${st.breakdowns}</td><td class="num">${Math.round(st.downtime)} min</td><td><div class="progress ${o.a>=.9?'ok':''}" style="margin:0"><i style="width:${Math.round(o.a*100)}%"></i></div><small>${pct(o.a)}</small></td><td><div class="actions">${st.down?`<button data-repair="${st.id}" class="primary">Reparo concluído</button>`:`<button data-stop="${st.id}">${s.stops[st.id]?'Retomar':'Registrar parada / falha'}</button>`}</div></td></tr>`;}).join('')}</tbody></table></div></div>
 ${s.stages.some(st=>(st.telemetry||[]).length)?`<div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Instrumentação e telemetria (PLC / IHM / IoT)</h2><div class="toolbar" style="margin:0"><span class="muted">${esc(s.settings.integration?.opcua?.endpoint||'')} · ${esc(s.settings.integration?.mqtt?.broker||'')} · somente leitura</span>${App.online?'<button id="sync-tags" class="small">Cadastrar tags no banco</button>':''}</div></div><div class="table-wrap"><table><thead><tr><th>Tag</th><th>Descrição</th><th>Setor · recurso</th><th>Fonte · endereço</th><th>Valor</th><th>Faixa / setpoint</th><th>Estado</th></tr></thead><tbody>${F.processReadings(s).map(r=>{const t=s.stages.find(x=>x.id===r.stage).telemetry.find(x=>x.tag===r.tag)||{};return `<tr><td class="mono">${esc(r.tag)}</td><td>${esc(r.description)}</td><td>${esc(r.stageName)}<small class="mono">${esc(r.resource||'')}</small></td><td><small class="mono">${esc(t.source||'opcua')} · ${esc(t.address||'—')}</small></td><td class="num">${r.value==null?'—':r.value.toFixed(r.unit==='un'?0:2)+' '+esc(r.unit)}${r.at?`<small>${time(r.at)}</small>`:''}</td><td class="num">${r.setpoint!=null?'sp '+r.setpoint+' ±'+(r.hi-r.setpoint).toFixed(1):(r.lo??'—')+' … '+(r.hi??'—')}</td><td>${r.state==='ok'?'<span class="badge ok">ok</span>':r.state==='deviation'?'<span class="badge alarm">desvio</span>':r.state==='nodata'?'<span class="badge">sem dados</span>':'<span class="badge warn">'+r.state+'</span>'}</td></tr>`;}).join('')}</tbody></table></div><div class="notice" style="margin:12px 0 0">Gateway: <code>python tools/opcua_gateway.py integration/${esc(s.project.code.toLowerCase())}-gateway.json</code> (adicione <code>--simulate</code> para validar sem PLC). Nenhum comando é escrito no PLC.</div></div>`:''}
 <div class="panel" style="margin-top:14px"><div class="panel-title"><h2>Histórico de manutenção</h2><span class="muted">eventos de falha, reparo e parada</span></div>${s.events.filter(e=>/parada|reparo|falha|retomad/i.test(e.text)&&!e.order).slice(0,20).map(e=>`<div class="event ${e.kind}"><time>${time(e.time)}</time><i></i><span>${esc(e.text)}</span></div>`).join('')||'<div class="empty">Sem eventos.</div>'}</div>`;}};

const kpi={render(){const s=App.state,k=F.kpis(s);const done=s.orders.filter(o=>o.status==='done');const buckets=[[0,8,'≤ 8 h'],[8,24,'8–24 h'],[24,72,'1–3 d'],[72,1e9,'> 3 d']].map(([a,b,l])=>[l,done.filter(o=>{const h=(o.completed-o.created)/60;return h>=a&&h<b;}).length]);
 $('view-kpi').innerHTML=`<div class="tiles"><div class="tile"><small>OEE</small><b>${pct(k.oee)}</b><small>A ${pct(k.availability)} · P ${pct(k.performance)} · Q ${pct(k.quality)}</small></div><div class="tile"><small>OTIF</small><b>${k.otif==null?'—':k.otif+'%'}</b><small>${done.length} concluídas</small></div><div class="tile"><small>Lead time médio</small><b>${k.leadTime?k.leadTime.toFixed(1):'—'}<em style="font:11px var(--sans);font-style:normal"> h</em></b><small>criação → expedição</small></div><div class="tile"><small>Throughput</small><b>${k.throughput.toFixed(1)}</b><small>un / dia</small></div><div class="tile"><small>WIP</small><b>${k.open}</b><small>${k.late} vencidas</small></div><div class="tile"><small>Ocupação agora</small><b>${k.load}%</b><small>${k.running}/${k.cap} posições</small></div></div>
 <div class="grid-2" style="margin-top:14px"><div class="panel"><div class="panel-title"><h2>OEE por setor</h2><span class="muted">disponibilidade × desempenho × qualidade</span></div><div class="bars">${s.stages.map(st=>{const o=F.oee(st);return bar(st.name,o.oee,` <small style="display:inline">A${Math.round(o.a*100)} P${Math.round(o.p*100)} Q${Math.round(o.q*100)}</small>`);}).join('')}</div></div>
 <div class="stack"><div class="panel"><div class="panel-title"><h2>Distribuição de lead time</h2><span class="muted">${done.length} ordens</span></div><div class="bars">${buckets.map(([l,n])=>bar(l,done.length?n/done.length:0,` <small style="display:inline">${n}</small>`)).join('')}</div></div>
 <div class="panel"><div class="panel-title"><h2>Trilha no PostgreSQL</h2>${App.online?'<button id="refresh-audit" class="small">Atualizar</button>':'<span class="tag warn">MODO LOCAL</span>'}</div>${App.online?(App.audit.length?`<div class="kv"><dt>Ordens no banco</dt><dd>${App.dbOrders.length} · ${App.dbOrders.filter(o=>o.status==='completed').length} concluídas · ${App.dbOrders.filter(o=>o.status==='running').length} em execução</dd><dt>Operações concluídas</dt><dd>${App.dbOrders.reduce((n,o)=>n+Number(o.ops_done),0)} / ${App.dbOrders.reduce((n,o)=>n+Number(o.ops_total),0)}</dd><dt>Reservas consumidas</dt><dd>${App.dbOrders.reduce((n,o)=>n+Number(o.consumed_reservations),0)}</dd></div><div style="margin-top:10px;max-height:220px;overflow:auto">${App.audit.map(a=>`<div class="event"><time>${new Date(a.at).toLocaleTimeString('pt-BR')}</time><i></i><span><b class="mono">${esc(a.table_name)}</b> ${esc(a.action)} ${esc(a.ref||'')}</span></div>`).join('')}</div>`:'<small>Clique em Atualizar para carregar auditoria (audit.events) e o estado relacional das ordens.</small>'):'<small>Conecte a API para ver auditoria imutável, operações e reservas gravadas no banco.</small>'}</div></div></div>`;}};

/* Gaveta lateral da OP: planejamento ao vivo, operações/recursos, apontamento, materiais e histórico */
const drawer={render(o){const s=App.state;const op=F.curOp(o);const plan=F.schedule(s,'rank',false);const jobs=plan.jobs.filter(j=>j.id===o.id);const fin=plan.finish[o.id];const pend=F.pendencies(s).filter(p=>p.order===o.id);const closed=['done','cancelled'].includes(o.status);const openList=s.orders.filter(x=>!['done','cancelled'].includes(x.status)).sort((a,b)=>a.rank-b.rank);const pos=openList.indexOf(o);
 const transitions=closed?[]:[['backlog','Carteira'],['planned','Planejada'],['released','Liberada']].filter(([k])=>k!==o.status&&!(o.status==='running'||o.status==='paused')||(k==='released'&&false));
 return `<div class="drawer-head"><div class="top"><div><h2>${esc(o.id)}</h2><div class="sub">${esc(o.client)} · ${esc(o.productCode)} · ${esc(s.products[o.product]?.name||'')} · rev. ${o.revision} · ${o.qty} un</div><div class="chips">${statusBadge(o)} ${o.priority==='Urgente'?'<span class="badge warn">Urgente</span>':''} ${closed?'':pickBadge(o)} ${o.rework?`<span class="badge purple">${o.rework} retrabalho(s)</span>`:''} ${!closed?`<span class="badge">#${pos+1} na sequência</span>`:''}</div></div><button class="close" data-close-drawer aria-label="Fechar">×</button></div>
  <div class="drawer-actions">${opControls(o).replace('<div class="actions">','').replace(/<\/div>$/,'')}${closed?'':`<button data-order="${o.id}" data-act="priority">${o.priority==='Urgente'?'Normalizar':'↑ Urgente'}</button><button data-order="${o.id}" data-act="up" title="Antecipar na sequência">▲</button><button data-order="${o.id}" data-act="down" title="Postergar na sequência">▼</button>${transitions.map(([k,l])=>`<button data-order="${o.id}" data-act="status" data-status="${k}">→ ${l}</button>`).join('')}<button data-order="${o.id}" data-act="cancel" class="danger ghost">Cancelar</button>`}</div></div>
  <div class="drawer-section"><h3>Planejamento <span class="muted">${fin?'término previsto '+time(fin)+(fin>o.due?' · <span style="color:var(--danger)">após o prazo</span>':' · dentro do prazo'):''}</span></h3>${closed?`<div class="kv"><dt>Criada</dt><dd>${F.fmtLong(o.created)}</dd><dt>Prazo</dt><dd>${F.fmtLong(o.due)}</dd><dt>Encerrada</dt><dd>${F.fmtLong(o.completed)}</dd></div>`:`<form id="drawer-plan"><input type="hidden" name="order" value="${o.id}"><div class="row"><label>Cliente<input name="client" value="${esc(o.client)}" maxlength="60"></label><label>Prioridade<select name="priority"><option ${o.priority==='Normal'?'selected':''}>Normal</option><option ${o.priority==='Urgente'?'selected':''}>Urgente</option></select></label></div><div class="row"><label>Prazo de entrega<input type="datetime-local" name="due" value="${F.toLocalInput(o.due)}" required></label><label>Início planejado (não antes de)<input type="datetime-local" name="plannedStart" value="${F.toLocalInput(o.plannedStart)}"></label></div><label>Observações<textarea name="notes" rows="2" maxlength="500">${esc(o.notes||'')}</textarea></label><div class="actions" style="margin-top:6px"><button class="primary" type="submit">Salvar e recalcular plano</button><button type="button" data-order="${o.id}" data-act="clearpins" class="ghost">Limpar fixações</button><button type="button" data-order="${o.id}" data-act="replan" class="ghost">Recalcular</button></div></form><div class="kv" style="margin-top:8px"><dt>Criada</dt><dd>${F.fmtLong(o.created)}</dd><dt>Liberada</dt><dd>${F.fmtLong(o.releasedAt)}</dd><dt>Início real</dt><dd>${F.fmtLong(o.startedAt)}</dd><dt>Trabalho restante</dt><dd>${minutes(F.remaining(s,o))}</dd></div>`}</div>
  <div class="drawer-section"><h3>Operações e recursos <span class="muted">${o.ops.filter(x=>x.status==='done').length}/${o.ops.length} concluídas</span></h3><div class="table-wrap" style="max-height:none;border:0"><table class="ops-table"><thead><tr><th>#</th><th>Setor</th><th>Recurso</th><th>Planejado</th><th>Real</th><th>Ação</th></tr></thead><tbody>${o.ops.map((x,k)=>{const st=s.stages[x.stage];const j=jobs.find(jj=>jj.seq===x.seq);const isCur=k===o.step&&!closed;return `<tr class="${isCur?'op-current':''}"><td class="num">${x.seq}${x.rework?'<small>retrab.</small>':''}</td><td>${opBadge(x)}${esc(st.name)}<small>${st.setup}+${st.minutes}·${o.qty} = ${Math.round(F.duration(s,o,x.stage))} min</small></td><td>${x.status==='pending'&&!closed?`<select data-op-field="lane" data-order="${o.id}" data-seq="${x.seq}" aria-label="Recurso"><option value="">auto${j?' ('+st.resources[j.lane]+')':''}</option>${st.resources.map((r,l)=>`<option value="${l}" ${x.lane===l?'selected':''}>${r}</option>`).join('')}</select>`:`<span class="mono">${x.lane!=null?st.resources[x.lane]:'—'}</span>`}</td><td class="num">${j?time(j.start)+'<small>→ '+time(j.end)+'</small>':(x.plannedStart?time(x.plannedStart):'—')}${x.notBefore?'<small style="color:var(--accent)">fixada ≥ '+time(x.notBefore)+'</small>':''}</td><td class="num">${x.start?time(x.start):'—'}${x.end?'<small>→ '+time(x.end)+'</small>':x.status==='running'?'<small style="color:var(--ok)">'+Math.round(s.time-x.start)+' min</small>':x.status==='paused'?'<small style="color:var(--warn)">pausada</small>':''}${x.status==='done'?`<small>${x.good} boas${x.scrap?' · '+x.scrap+' NC':''}</small>`:''}</td><td>${isCur?opControls(o):(x.status==='pending'&&!closed&&x.notBefore?`<input type="datetime-local" data-op-field="notBefore" data-order="${o.id}" data-seq="${x.seq}" value="${F.toLocalInput(x.notBefore)}" style="font-size:10px;padding:2px 4px">`:'')}</td></tr>`;}).join('')}</tbody></table></div></div>
  ${(()=>{const op=F.curOp(o);if(!op||op.status!=='running'||op.lane==null)return '';const res=s.stages[op.stage].resources[op.lane];const rd=F.processReadings(s).filter(r=>r.resource===res);if(!rd.length)return '';return `<div class="drawer-section"><h3>Processo · ${esc(res)} <span class="muted">telemetria PLC/IoT</span></h3><div class="kv">${rd.map(r=>`<dt>${esc(r.description||r.tag)}<small>${esc(r.tag)}</small></dt><dd>${r.value==null?'<span class="muted">sem dados</span>':r.value.toFixed(1)+' '+esc(r.unit)}${r.setpoint!=null?' <small style="display:inline">sp '+r.setpoint+'</small>':''} ${r.state==='deviation'?'<span class="badge alarm">desvio</span>':r.state==='ok'?'<span class="badge ok">ok</span>':r.state==='nodata'?'':'<span class="badge warn">'+r.state+'</span>'}</dd>`).join('')}</div>${s.products[o.product].params&&Object.keys(s.products[o.product].params).length?`<small style="margin-top:8px">Receita ${esc(o.productCode)} rev. ${o.revision}: ${Object.entries(s.products[o.product].params).map(([k,v])=>k+' '+v).join(' · ')}</small>`:''}</div>`;})()}
  <div class="drawer-section"><h3>Materiais e picking <span class="muted">${o.consumed?'kit entregue '+time(o.picking.at)+' · '+esc(o.picking.by||''):(pend.length?pend.length+' pendência(s)':'kit reservado · aguardando picking')}</span></h3><div class="table-wrap" style="max-height:none;border:0"><table class="ops-table"><thead><tr><th>Item</th><th>Necessário</th><th>Físico</th><th>Situação</th></tr></thead><tbody>${o.kit.map(k=>{const x=s.stock[k.item];const pd=pend.find(p=>p.item===k.item);return `<tr><td>${esc(x.code)}<small>${esc(x.name)}</small></td><td class="num">${k.qty} ${x.unit}</td><td class="num">${x.onHand}</td><td>${o.consumed?'<span class="badge ok">consumido</span>':pd?`<span class="badge alarm">falta ${pd.missing}</span>${pd.eta?'<small>compra chega '+time(pd.eta)+'</small>':'<small><button class="small" data-receive="'+k.item+'" data-kind="purchase">comprar</button></small>'}`:'<span class="badge info">reservado</span>'}</td></tr>`;}).join('')}</tbody></table></div>${!o.consumed&&!closed?`<div class="actions" style="margin-top:8px"><button data-order="${o.id}" data-act="pick" class="${pend.length?'':'primary'}" ${pend.length?'disabled':''}>Confirmar picking e entregar kit</button></div>`:''}</div>
  <div class="drawer-section"><h3>Histórico</h3>${s.events.filter(e=>e.order===o.id).slice(0,25).map(e=>`<div class="event ${e.kind}"><time>${time(e.time)}</time><i></i><span>${esc(e.text)}</span></div>`).join('')||'<small>Sem eventos.</small>'}</div>`;}};

return {metrics,projects,portfolio,twin,mes,aps,plm,ppcp,stock,quality,maint,kpi,drawer};
})();
